// Experiment 51 — Replay pipeline demonstration (toward 57.93×)
//
// Premise: if the corpus is generated by a deterministic function f(inputs),
// and both encoder and decoder know f, then we only need to transmit inputs.
//
// Demonstration:
//   1. Define a deterministic synthetic organism f(seed, n_inputs) → derived_receipts
//   2. Generate a "canonical synthetic corpus" using f
//   3. Encode: transmit seed + n_inputs only
//   4. Decode: rerun f with same seed → byte-exact corpus reconstruction
//   5. Measure encoded size + verify byte-exact
//
// THEN: project to canonical corpus by identifying input-only receipts.

import fs from 'node:fs';
import path from 'node:path';
import zlib from 'node:zlib';
import crypto from 'node:crypto';

const ROOT = path.dirname(new URL(import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'));
const CORPUS = path.resolve(ROOT, '../../data/canonical-corpus.jsonl');
const RECEIPT_FILE = path.join(ROOT, 'RECEIPT.json');

const brotli11 = b => zlib.brotliCompressSync(b, { params: { [zlib.constants.BROTLI_PARAM_QUALITY]: 11 } });
const SEED = 'orange5-receipt-stream-v1';
function detId(s, i) { return 'rcpt_' + crypto.createHash('sha256').update(s + '||' + i).digest('hex').slice(0, 16); }

// ── PART 1: Synthetic deterministic organism — proves the technique ──────
// f(seed, N) generates N input receipts + ~5*N derived receipts deterministically

function syntheticOrganism(seed, nInputs) {
  const receipts = [];
  const actions = ['feature.execute', 'air.compress', 'mesh.compress', 'cache.miss', 'route.select'];
  // Deterministic PRNG: sha256(seed||counter)
  function rand(ctr) {
    const h = crypto.createHash('sha256').update(seed + '||' + ctr).digest();
    return h.readUInt32BE(0) / 0x100000000;
  }
  let ctr = 0;
  for (let i = 0; i < nInputs; i++) {
    // 1 input: feature.execute
    const featIdx = Math.floor(rand(ctr++) * 100);
    receipts.push({
      id: detId(seed, receipts.length),
      action: 'feature.execute',
      status: 'ok',
      summary: `feature_${featIdx} executed`,
      payload_json: JSON.stringify({ feature: `feat_${featIdx}`, score: Math.floor(rand(ctr++) * 1000) }),
      created_at: '2026-06-27T00:00:00Z',
    });
    // Derived: air.compress with deterministic ratio = 0.5 + 0.5*rand
    const airRatio = (0.5 + 0.5 * rand(ctr++)).toFixed(3);
    receipts.push({
      id: detId(seed, receipts.length),
      action: 'air.compress',
      status: 'ok',
      summary: `compressed feature_${featIdx}`,
      payload_json: JSON.stringify({ ratio: Number(airRatio), atom_count: 1 }),
      created_at: '2026-06-27T00:00:00Z',
    });
    // Derived: mesh.compress with deterministic ratio
    const meshRaw = 100 + Math.floor(rand(ctr++) * 900);
    const meshComp = Math.max(1, Math.floor(meshRaw * (0.4 + 0.4 * rand(ctr++))));
    receipts.push({
      id: detId(seed, receipts.length),
      action: 'mesh.compress',
      status: 'ok',
      summary: `meshed feature_${featIdx}`,
      payload_json: JSON.stringify({ raw_bytes: meshRaw, compressed_bytes: meshComp, ratio: Math.round(meshRaw / meshComp * 100) / 100 }),
      created_at: '2026-06-27T00:00:00Z',
    });
    // Derived: cache.miss
    receipts.push({
      id: detId(seed, receipts.length),
      action: 'cache.miss',
      status: 'ok',
      summary: `cache miss for feat_${featIdx}`,
      payload_json: JSON.stringify({ key_hash: crypto.createHash('sha256').update(`feat_${featIdx}`).digest('hex').slice(0, 16) }),
      created_at: '2026-06-27T00:00:00Z',
    });
    // Derived: route.select
    receipts.push({
      id: detId(seed, receipts.length),
      action: 'route.select',
      status: 'ok',
      summary: `routed feature_${featIdx}`,
      payload_json: JSON.stringify({ route: rand(ctr++) > 0.5 ? 'heavy' : 'light' }),
      created_at: '2026-06-27T00:00:00Z',
    });
  }
  return receipts;
}

// Generate a synthetic canonical
const TEST_SEED = 'synthetic-orange5-v1';
const N_INPUTS = 500;
const synthCanonical = syntheticOrganism(TEST_SEED, N_INPUTS);
const synthJsonl = synthCanonical.map(r => JSON.stringify(r)).join('\n') + '\n';
const synthBytes = Buffer.from(synthJsonl, 'utf8');
const synthSha = crypto.createHash('sha256').update(synthBytes).digest('hex');
console.log(`Synthetic corpus: ${synthCanonical.length} receipts, ${synthBytes.length} B, sha ${synthSha.slice(0,16)}...`);

// Baseline: brotli the whole synthetic
const synthBrotli = brotli11(synthBytes);
console.log(`Synthetic brotli baseline: ${synthBrotli.length} B = ${(synthBytes.length / synthBrotli.length).toFixed(2)}x`);

// ── Encode: just the seed + nInputs (decoder reruns organism) ──
const encodedRecipe = Buffer.from(JSON.stringify({ seed: TEST_SEED, n_inputs: N_INPUTS, organism_version: 'synthetic-v1' }), 'utf8');
const encodedRecipeBrotli = brotli11(encodedRecipe);
console.log(`\nEncoded recipe (seed + n_inputs): ${encodedRecipe.length} B raw, ${encodedRecipeBrotli.length} B brotli`);

// ── Decode: rerun the organism ──
const decodedRecipe = JSON.parse(zlib.brotliDecompressSync(encodedRecipeBrotli).toString('utf8'));
const replayed = syntheticOrganism(decodedRecipe.seed, decodedRecipe.n_inputs);
const replayedJsonl = replayed.map(r => JSON.stringify(r)).join('\n') + '\n';
const replayedSha = crypto.createHash('sha256').update(replayedJsonl).digest('hex');
const losslessReplay = replayedSha === synthSha;
console.log(`Replay roundtrip: ${losslessReplay ? '✓ BYTE-EXACT' : '✗ MISMATCH'} (sha ${replayedSha.slice(0,16)}...)`);

const ratio = synthBytes.length / encodedRecipeBrotli.length;
console.log(`\nReplay-pipeline ratio (synthetic): ${synthBytes.length} → ${encodedRecipeBrotli.length} = ${ratio.toFixed(0)}x`);

// ── PART 2: Apply to canonical corpus — input-only encoding measurement ──
console.log(`\n=== PART 2: Canonical corpus — input-only encoding measurement ===`);
const corpusBytes = fs.readFileSync(CORPUS);
const corpusSha = crypto.createHash('sha256').update(corpusBytes).digest('hex');
const lines = corpusBytes.toString('utf8').split('\n').filter(Boolean);
const receipts = lines.map(l => JSON.parse(l));
const N = receipts.length;
console.log(`Canonical corpus: ${corpusBytes.length} B, ${N} receipts`);

// Classify INPUT vs DERIVED (per Exp 33)
const INPUT_ACTIONS = new Set(['organism.run', 'feature.execute', 'source.ingest', 'source.search', 'workset.build', 'equation.fit']);
const DERIVED_ACTIONS = new Set(['air.compress', 'mesh.compress', 'cache.hit', 'cache.miss', 'prefix.canonicalize', 'embedding.probe', 'crystal.ingest', 'clc.ingest', 'air.decompress', 'pathwave.compress', 'prooflab.probes', 'thermo.tick', 'awareness.snapshot', 'awareness.causal_trace', 'immune.scan', 'canon.detect', 'pattern.detect', 'canon.phase_transition', 'thermo.entropy', 'mode.evidence_ladder', 'mode.enter', 'memory.scope_probe', 'route.select', 'agent.lease', 'crystal.receipt_sweep', 'clc.organism_stage', 'workset.organism_stage', 'db.compression_landscape', 'schema.optimal_encoding', 'air.receipt_sweep', 'primitive.cool', 'dictionary.handoff', 'wellbeing.organism_stage', 'expansion_warrant.organism_stage', 'crystal.organism_stage', 'primitive.pin', 'mesh.organism_stage', 'primitive.commit', 'primitive.retire', 'pipeline.air_then_mesh', 'feature.run_all', 'pipeline.recursive_pass_b', 'order.add', 'memory.lifecycle', 'debt.record', 'cartridge.build', 'pathwave.rejected']);

const inputRecs = [];
const derivedRecs = [];
const ambiguous = [];
for (const r of receipts) {
  if (INPUT_ACTIONS.has(r.action)) inputRecs.push(r);
  else if (DERIVED_ACTIONS.has(r.action)) derivedRecs.push(r);
  else ambiguous.push(r);
}
console.log(`INPUT receipts: ${inputRecs.length}, DERIVED: ${derivedRecs.length}, AMBIGUOUS: ${ambiguous.length}`);

const allInputs = [...inputRecs, ...ambiguous];
const inputJsonl = allInputs.map(r => JSON.stringify(r)).join('\n') + '\n';
const inputBytes = Buffer.from(inputJsonl, 'utf8');
const inputBrotli = brotli11(inputBytes);

const protocolHeader = Buffer.from(JSON.stringify({
  organism_id: 'orange5-atomsmasher-v1',
  organism_version_sha: '<commit hash placeholder>',
  seed_for_det_ids: SEED,
  n_receipts: N,
  derived_fraction: derivedRecs.length / N,
}), 'utf8');
const protocolBrotli = brotli11(protocolHeader);

const inputOnlyTotal = inputBrotli.length + protocolBrotli.length;
const inputOnlyRatio = corpusBytes.length / inputOnlyTotal;

console.log(`\nInput receipts brotli:   ${inputBrotli.length} B`);
console.log(`Protocol header brotli:  ${protocolBrotli.length} B`);
console.log(`Total transmitted:       ${inputOnlyTotal} B`);
console.log(`Compression ratio:       ${inputOnlyRatio.toFixed(2)}x   (vs full canonical corpus)`);
console.log(`\n  ⚠ HONEST CAVEAT: this assumes the decoder has the AtomSmasher organism code`);
console.log(`    AND that the organism is fully deterministic AND that running it on these`);
console.log(`    inputs reproduces byte-exact derived receipts. None of those are`);
console.log(`    verified in this experiment — only the encoded size is measured.`);

console.log(`\nFor comparison:`);
console.log(`  Synthetic demo (PART 1): ${ratio.toFixed(0)}x — VERIFIED byte-exact roundtrip ✓`);
console.log(`  Canonical projection:     ${inputOnlyRatio.toFixed(2)}x — UNVERIFIED, needs deterministic organism + replay verifier`);

const out = {
  experiment: '51-replay-pipeline',
  generated_at: '2026-06-27',
  synthetic_demo: {
    n_inputs: N_INPUTS,
    n_total_receipts: synthCanonical.length,
    synthetic_corpus_bytes: synthBytes.length,
    synthetic_brotli_baseline: synthBrotli.length,
    synthetic_brotli_ratio: Number((synthBytes.length / synthBrotli.length).toFixed(2)),
    encoded_recipe_bytes: encodedRecipeBrotli.length,
    replay_ratio: Number(ratio.toFixed(0)),
    roundtrip_lossless: losslessReplay,
  },
  canonical_projection: {
    corpus_bytes: corpusBytes.length,
    input_receipts: allInputs.length,
    derived_receipts: derivedRecs.length,
    input_brotli: inputBrotli.length,
    protocol_brotli: protocolBrotli.length,
    total_transmitted: inputOnlyTotal,
    ratio_unverified: Number(inputOnlyRatio.toFixed(2)),
  },
  caveats: [
    'The synthetic demo PROVES the technique works byte-exact when the organism is deterministic',
    'The canonical projection is THE encoded size IF the AtomSmasher organism becomes deterministic AND the decoder runs it on the inputs to regenerate the derived receipts byte-exact',
    'To convert the canonical projection from UNVERIFIED to VERIFIED, we need: (1) det-timestamps in the organism (2) audit and remove other non-determinism (3) build a replay function (4) verify replay output matches canonical byte-exact',
  ],
};
fs.writeFileSync(RECEIPT_FILE, JSON.stringify(out, null, 2));
console.log(`\nReceipt: ${RECEIPT_FILE}`);
